#include <stdio.h>
#include <stdlib.h>

#define MAXSUM 1000000

static int cnt[MAXSUM + 2];

int main(void) {
    int n;
    long long s;
    if (scanf("%d", &n) != 1) return 0;
    if (scanf("%lld", &s) != 1) return 0;

    long long ans = 0;
    long long run = 0;   /* soma dos prefixos */
    cnt[0] = 1;          /* prefixo vazio P[0] = 0 */

    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) break;
        run += x;
        if (run >= s) {
            ans += cnt[run - s];
        }
        cnt[run]++;
    }

    printf("%lld\n", ans);
    return 0;
}
```

**Explicação da abordagem:**

- Usamos soma de prefixos: um intervalo `(i, j]` tem soma `S` se e somente se `P[j] - P[i] = S`, ou seja, `P[i] = P[j] - S`.
- Como `Xi ≥ 0` e a soma total é no máximo `10 × 100000 = 1.000.000`, os valores de prefixo cabem em `[0, 1.000.000]`, permitindo uma tabela de contagem direta (sem hash).
- Para cada posição `j`, somamos à resposta quantos prefixos anteriores têm valor `P[j] - S` (apenas se `P[j] ≥ S`), e depois registramos o prefixo atual na tabela — garantindo que apenas prefixos com índice menor que `j` sejam contados.
- A resposta pode chegar a `N(N+1)/2 ≈ 5×10⁹` (caso `S = 0` e todos `Xi = 0`), por isso usamos `long long`.

**Complexidade:** tempo `O(N + S)`, memória `O(S)` (~4 MB).

